-- pg_morlet 0.3.17 -> 0.3.18 (generated by tests/gen_upgrade.py; do not edit).
-- Calibration sets: evidence follows recordings, not reusable IDs (#621); members record their
-- interpretation revisions (#620). Existing calibration tables are brought up to date (below).
-- morlet_interpretation_revisions, morlet_label_interpretation: no revision claimed when row policies could
-- hide revisions (#608).
-- morlet_sample_utc: the piece of a sample from the anchors around it, by index (#546).
\echo Use "ALTER EXTENSION pg_morlet UPDATE TO '0.3.18'" to load this file. \quit

CREATE FUNCTION public.morlet_calibration_bind_refs(collection regclass)
RETURNS void LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; rel regclass; refs regclass; ctx record;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  rel:=public.morlet_calibration_relation(collection);
  SELECT * INTO ctx FROM public.morlet_context_relations(collection);
  IF NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=rel AND attname='ref_key' AND NOT attisdropped) THEN
    EXECUTE format('ALTER TABLE %s ADD COLUMN ref_key uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE',rel);
    EXECUTE format('ALTER TABLE %s ALTER COLUMN ref_key DROP DEFAULT',rel);
  END IF;
  refs:=to_regclass(format('%I.%I',s,c||'_calibration_refs'));
  IF refs IS NULL THEN
    EXECUTE format('CREATE TABLE %1$I.%2$I (ref_key uuid NOT NULL, recording_id text NOT NULL,
      live text REFERENCES %1$I.%3$I(recording_id) ON DELETE SET NULL, PRIMARY KEY(ref_key,recording_id))',
      s,c||'_calibration_refs',c);
    refs:=format('%I.%I',s,c||'_calibration_refs')::regclass;
    -- Before the guard exists: a member whose recording is gone starts cut, never absent. So does one whose label
    -- is gone: labels are deleted with their recording and label IDs are never reused, so a recording recreated
    -- under the same ID before this table existed is recognised too.
    EXECUTE format('INSERT INTO %s(ref_key,recording_id,live) SELECT x.ref_key,r,
      CASE WHEN EXISTS(SELECT 1 FROM %s y WHERE y.recording_id=r) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x.members) m
        WHERE m->>''recording_id''=r AND NOT EXISTS(SELECT 1 FROM %s l WHERE l.label_id=(m->>''label_id'')::bigint
          AND l.recording_id=r)) THEN r END
      FROM %s x,unnest(x.recording_ids) r',refs,collection,ctx.labels,rel);
    EXECUTE format('CREATE TRIGGER morlet_calibration_refs_guard BEFORE INSERT OR UPDATE OR DELETE ON %s
      FOR EACH ROW EXECUTE FUNCTION public.morlet_calibration_refs_guard()',refs);
    EXECUTE format('CREATE TRIGGER morlet_calibration_refs_truncate BEFORE TRUNCATE ON %s
      FOR EACH STATEMENT EXECUTE FUNCTION public.morlet_calibration_refs_guard()',refs);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname='morlet_calibration_refs') THEN
    EXECUTE format('CREATE TRIGGER morlet_calibration_refs AFTER INSERT OR UPDATE OF members ON %s
      FOR EACH ROW EXECUTE FUNCTION public.morlet_calibration_track_refs()',rel);
  END IF;
  IF public.morlet_row_security_enabled(collection) THEN PERFORM public.morlet_enable_row_security(collection); END IF;
END $$;

CREATE FUNCTION public.morlet_calibration_refs_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; ok boolean;
BEGIN
  SELECT n.nspname,left(cl.relname,-length('_calibration_refs')) INTO s,c
    FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=TG_RELID;
  IF TG_OP='INSERT' AND NEW.live IS NOT DISTINCT FROM NEW.recording_id THEN
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I.%I x WHERE x.ref_key=$1 AND $2=ANY(x.recording_ids))',s,c||'_calibration_sets')
      INTO ok USING NEW.ref_key,NEW.recording_id;
    IF ok THEN RETURN NEW; END IF;
  ELSIF TG_OP='UPDATE' AND NEW.live IS NULL AND OLD.live IS NOT NULL AND NEW.ref_key=OLD.ref_key
      AND NEW.recording_id=OLD.recording_id THEN
    EXECUTE format('SELECT NOT EXISTS(SELECT 1 FROM %I.%I y WHERE y.recording_id=$1)',s,c) INTO ok USING OLD.live;
    IF ok THEN RETURN NEW; END IF;
  END IF;
  RAISE EXCEPTION 'calibration references are maintained by MorletDB; a deleted member recording stays deleted';
END $$;

CREATE FUNCTION public.morlet_calibration_track_refs()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE refs regclass;
BEGIN
  IF TG_OP='UPDATE' AND NEW.recording_ids IS NOT DISTINCT FROM OLD.recording_ids THEN RETURN NULL; END IF;
  SELECT to_regclass(format('%I.%I',n.nspname,left(cl.relname,-length('_calibration_sets'))||'_calibration_refs')) INTO refs
    FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=TG_RELID;
  EXECUTE format('INSERT INTO %s(ref_key,recording_id,live) SELECT $1,r,r FROM unnest($2) r ON CONFLICT DO NOTHING',refs)
    USING NEW.ref_key,NEW.recording_ids;
  RETURN NULL;
END $$;

CREATE FUNCTION public.morlet_interpretation_history_complete(history regclass)
RETURNS boolean LANGUAGE sql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
  SELECT has_table_privilege(history,'SELECT') AND (NOT row_security_active(history) OR (
    EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=history AND p.polname='morlet_follows_recording'
      AND p.polpermissive AND p.polcmd='*' AND p.polroles='{0}'::oid[])
    AND NOT EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=history AND (p.polname<>'morlet_follows_recording'
      OR NOT p.polpermissive OR p.polcmd<>'*' OR p.polroles<>'{0}'::oid[]))))
$$;

CREATE OR REPLACE FUNCTION public.morlet_enable_row_security(collection regclass)
RETURNS integer LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; t record; covered integer:=0; cond text; chk text;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  FOR t IN SELECT cl.relname FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
      WHERE n.nspname=s AND cl.relkind='r' AND (cl.relname IN (c||'_chunks',c||'_segments',c||'_envelopes',c||'_ctx',
        c||'_ctx_segments',c||'_ctx_values',c||'_labels',c||'_acq',c||'_acq_channels',c||'_rollups',
        c||'_episodes',c||'_ledger',c||'_kept_summaries',c||'_memory_runs',c||'_time_anchors',c||'_interpretation',c||'_calibration_sets',c||'_calibration_refs') OR (left(cl.relname,length(c)+8)=c||'_probes_' AND substr(cl.relname,length(c)+9) ~ '^[0-9]+$'))
      ORDER BY cl.relname LOOP
    IF t.relname=c||'_calibration_sets' THEN
      -- A manifest is indivisible: never disclose a partly visible multi-recording set. Deleting a member recording
      -- cuts its reference (ON DELETE SET NULL), and a later recording under the same ID does not restore it, so
      -- evidence never follows a reused identifier (references are written with the revision and only cut after).
      chk:=format('recording_ids <@ ARRAY(SELECT x.recording_id FROM %s x)',collection);
      cond:=format('%s AND NOT EXISTS(SELECT 1 FROM %I.%I r WHERE r.ref_key=%I.ref_key AND r.live IS NULL
        AND r.recording_id=ANY(%I.recording_ids))',chk,s,c||'_calibration_refs',t.relname,t.relname);
    ELSIF t.relname=c||'_ctx_values' THEN
      cond:=format('EXISTS(SELECT 1 FROM %I.%I x WHERE x.segment_id=%I.segment_id)',s,c||'_ctx_segments',t.relname);
      chk:=cond;
    ELSIF t.relname=c||'_acq' THEN
      -- visible through a visible channel, and to its creator until it has one (inserting an acquisition
      -- precedes its channels)
      -- (the channel lookup runs in a function: the channel policy refers to this table, and a subquery here
      -- would make the policies recursive)
      cond:=format('public.morlet_acquisition_has_visible_channel(%L::regclass,%I.acquisition_id)
        OR public.morlet_inserted_by_current_transaction(%I.xmin)',format('%I.%I',s,c||'_acq_channels'),t.relname,t.relname);
      chk:='true';
    ELSIF t.relname=c||'_memory_runs' THEN
      -- Episodic memory (#438): a run has no recording of its own and may span several, so it is visible to the
      -- role that started it; its ledger rows follow their recordings. Older tables get the column here.
      EXECUTE format('ALTER TABLE %I.%I ADD COLUMN IF NOT EXISTS started_by name NOT NULL DEFAULT current_user',s,t.relname);
      cond:=format('%I.started_by = current_user',t.relname);
      chk:=cond;
    ELSIF t.relname=c||'_acq_channels' THEN
      -- a channel row follows its recording; adding or moving one also needs its acquisition to be visible,
      -- so a recording cannot join another tenant's acquisition by naming its ID (a foreign key is not
      -- an authorization check)
      cond:=format('%I.recording_id = ANY (ARRAY(SELECT x.recording_id FROM %s x))',t.relname,collection);
      chk:=format('%s AND EXISTS(SELECT 1 FROM %I.%I a WHERE a.acquisition_id=%I.acquisition_id)',
        cond,s,c||'_acq',t.relname);
    ELSE
      -- An uncorrelated ARRAY(...) becomes an InitPlan, which keeps scans parallel; a correlated
      -- EXISTS compiled to a parallel-restricted SubPlan and made exact search 3x slower.
      cond:=format('%I.recording_id = ANY (ARRAY(SELECT x.recording_id FROM %s x))',t.relname,collection);
      chk:=cond;
    END IF;
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY',s,t.relname);
    EXECUTE format('DROP POLICY IF EXISTS morlet_follows_recording ON %I.%I',s,t.relname);
    EXECUTE format('CREATE POLICY morlet_follows_recording ON %I.%I USING (%s) WITH CHECK (%s)',s,t.relname,cond,chk);
    covered:=covered+1;
  END LOOP;
  RETURN covered;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_calibration_capture(collection regclass,members jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog
  SET timezone='UTC' SET extra_float_digits=3 AS $$
DECLARE rel record; m jsonb; rec jsonb; lab jsonb; contexts jsonb; acquisitions jsonb;
  result jsonb:='[]'; rid text; lo bigint; hi bigint; label_id bigint; total bigint:=0;
  s text; c text; channels regclass; raw bytea; history regclass; rec_revision jsonb; lab_revision jsonb;
BEGIN
  IF jsonb_typeof(members) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'members must be an array'; END IF;
  IF jsonb_array_length(members) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'expected 1..100 members'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(members)) <>
     (SELECT count(DISTINCT (value->'recording_id',value->'start_sample',value->'end_sample')) FROM jsonb_array_elements(members)) THEN
    RAISE EXCEPTION 'duplicate calibration member';
  END IF;
  SELECT * INTO rel FROM public.morlet_context_relations(collection);
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  channels:=to_regclass(format('%I.%I',s,c||'_acq_channels'));
  history:=public.morlet_interpretation_relation(collection);
  FOR m IN SELECT value FROM jsonb_array_elements(members) ORDER BY value::text COLLATE "C" LOOP
    IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR
       (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(m) key) IS DISTINCT FROM
       ARRAY['end_sample','label_id','recording_id','start_sample']::text[] THEN
      RAISE EXCEPTION 'member requires exactly recording_id, start_sample, end_sample, label_id';
    END IF;
    IF jsonb_typeof(m->'recording_id') IS DISTINCT FROM 'string' OR
       jsonb_typeof(m->'start_sample') IS DISTINCT FROM 'number' OR
       jsonb_typeof(m->'end_sample') IS DISTINCT FROM 'number' OR
       jsonb_typeof(m->'label_id') IS DISTINCT FROM 'number' OR (m->>'start_sample') !~ '^[0-9]+$' OR (m->>'end_sample') !~ '^[0-9]+$' OR
       (m->>'label_id') !~ '^[0-9]+$' OR m->>'start_sample' IS NULL OR
       m->>'end_sample' IS NULL OR m->>'label_id' IS NULL THEN RAISE EXCEPTION 'invalid member fields'; END IF;
    rid:=m->>'recording_id'; lo:=(m->>'start_sample')::bigint; hi:=(m->>'end_sample')::bigint;
    label_id:=(m->>'label_id')::bigint;
    IF hi<=lo OR hi-lo>1000000 THEN RAISE EXCEPTION 'each member requires 1..1000000 samples'; END IF;
    total:=total+hi-lo;
    IF total>4000000 THEN RAISE EXCEPTION 'calibration set exceeds 4000000 samples'; END IF;
    EXECUTE format('SELECT jsonb_build_object(''sample_rate_hz'',sample_rate_hz,''channel'',channel,''unit'',unit,
      ''metadata'',metadata) FROM %s WHERE recording_id=$1',collection) INTO rec USING rid;
    IF rec IS NULL THEN RAISE EXCEPTION 'member recording unavailable'; END IF;
    -- The label's own columns, named: a column another feature adds later (interpretation_revision, #600) must not
    -- make an approved, unchanged member look changed.
    EXECUTE format('SELECT jsonb_build_object(''label_id'',l.label_id,''recording_id'',l.recording_id,
      ''start_sample'',l.start_sample,''end_sample'',l.end_sample,''label'',l.label,''note'',l.note,
      ''author'',l.author,''created_at'',l.created_at,''retracted'',l.retracted),to_jsonb(l)->''interpretation_revision''
      FROM %s l WHERE label_id=$1 AND recording_id=$2
      AND start_sample<=$3 AND end_sample>=$4 AND NOT retracted',rel.labels)
      INTO lab,lab_revision USING label_id,rid,lo,hi;
    IF lab IS NULL THEN RAISE EXCEPTION 'member requires a visible active label covering its interval'; END IF;
    -- The interpretation the member was captured under (#620): the recording's current revision and the one its label
    -- was written under. 'unversioned' without a history, or for a label older than it; 'unknown' when the history
    -- exists but this role cannot read it, so unreadable history is never reported as unchanged.
    IF history IS NULL THEN rec_revision:='"unversioned"';
    ELSIF NOT public.morlet_interpretation_history_complete(history) THEN
      -- unreadable, or row policies could hide revisions of a visible recording
      rec_revision:='"unknown"';
    ELSE
      EXECUTE format('SELECT to_jsonb(coalesce(max(revision),0)) FROM %s WHERE recording_id=$1',history)
        INTO rec_revision USING rid;
    END IF;
    lab_revision:=CASE WHEN history IS NULL OR lab_revision IS NULL OR lab_revision='null' THEN '"unversioned"'
      ELSE lab_revision END;
    EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.ctx_id),''[]''::jsonb) FROM %1$s x
      WHERE recording_id=$1 AND start_sample<$3 AND coalesce(end_sample,start_sample+1)>$2
      AND NOT retracted AND NOT EXISTS(SELECT 1 FROM %1$s y WHERE y.supersedes=x.ctx_id)',rel.ctx)
      INTO contexts USING rid,lo,hi;
    acquisitions:='[]';
    IF channels IS NOT NULL THEN
      EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.acquisition_id),''[]''::jsonb)
        FROM %s x WHERE recording_id=$1',channels) INTO acquisitions USING rid;
    END IF;
    raw:=public.morlet_read_interval_raw(collection,rid,lo,hi);
    result:=result||jsonb_build_array(m||jsonb_build_object('recording',rec,'label',lab,'context',contexts,
      'acquisitions',acquisitions,'acquisition_identity',CASE WHEN acquisitions='[]'::jsonb THEN 'unknown' ELSE 'recorded' END,
      'sample_sha256',encode(sha256(raw),'hex'),'sample_encoding','ieee754-f64-le',
      'time_axis_version',public.morlet_time_axis_version(collection,rid),
      'interpretation_revision',rec_revision,'label_revision',lab_revision,
      'availability','unknown'));
  END LOOP;
  RETURN jsonb_build_object('format','morlet-calibration-v1','collection',collection::text,
    'representation',jsonb_build_object('kind','raw','version',1),'members',result,
    'causal_replay',false,'retention','reference-only');
END $$;

CREATE OR REPLACE FUNCTION public.morlet_calibration_guard()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE coll regclass:=TG_ARGV[0]::regclass; captured jsonb;
BEGIN
  IF TG_OP='TRUNCATE' OR TG_OP='DELETE' THEN RAISE EXCEPTION 'calibration revisions cannot be removed'; END IF;
  IF current_setting('transaction_isolation') NOT IN ('repeatable read','serializable') THEN
    RAISE EXCEPTION 'calibration writes require REPEATABLE READ or SERIALIZABLE';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.approved THEN RAISE EXCEPTION 'create a draft before approval'; END IF;
    NEW.created_by:=current_user; NEW.created_at:=transaction_timestamp(); NEW.ref_key:=gen_random_uuid();
  ELSE
    IF OLD.approved THEN RAISE EXCEPTION 'approved calibration revision is immutable; create another revision'; END IF;
    IF (NEW.set_id,NEW.revision) IS DISTINCT FROM (OLD.set_id,OLD.revision) THEN
      RAISE EXCEPTION 'calibration revision identity is immutable';
    END IF;
    NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.ref_key:=OLD.ref_key;
  END IF;
  IF NEW.approved THEN
    IF NOT pg_has_role(current_user,TG_ARGV[1],'MEMBER') THEN
      RAISE EXCEPTION 'calibration approval requires membership of role %',TG_ARGV[1] USING ERRCODE='42501';
    END IF;
    IF NEW.members IS DISTINCT FROM OLD.members THEN RAISE EXCEPTION 'approval cannot edit membership'; END IF;
    IF NEW.approval_reason IS NULL OR btrim(NEW.approval_reason)='' THEN RAISE EXCEPTION 'approval reason required'; END IF;
    captured:=public.morlet_calibration_capture(coll,NEW.members);
    IF captured IS DISTINCT FROM OLD.manifest THEN RAISE EXCEPTION 'draft evidence changed; explicitly refresh the draft before approval'; END IF;
    NEW.approved_by:=current_user; NEW.approved_at:=transaction_timestamp();
  ELSE
    NEW.approved_by:=NULL; NEW.approved_at:=NULL; NEW.approval_reason:=NULL;
    captured:=public.morlet_calibration_capture(coll,NEW.members);
  END IF;
  -- All derived/audit columns are database generated, including on direct SQL writes.
  SELECT jsonb_agg(value ORDER BY value::text COLLATE "C") INTO NEW.members FROM jsonb_array_elements(NEW.members);
  NEW.manifest:=captured;
  NEW.manifest_text:=captured::text;
  NEW.manifest_sha256:=encode(sha256(convert_to(NEW.manifest_text,'UTF8')),'hex');
  SELECT array_agg(DISTINCT value->>'recording_id' ORDER BY value->>'recording_id') INTO NEW.recording_ids
    FROM jsonb_array_elements(NEW.members);
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_enable_calibration_sets(collection regclass,approver_role regrole)
RETURNS regclass LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; rel regclass; owner oid; approver_name text;
BEGIN
  SELECT rolname INTO STRICT approver_name FROM pg_roles WHERE oid=approver_role;
  SELECT n.nspname,cl.relname,cl.relowner INTO s,c,owner FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE cl.oid=collection;
  IF NOT pg_has_role(current_user,owner,'USAGE') THEN RAISE EXCEPTION 'collection owner required' USING ERRCODE='42501'; END IF;
  IF octet_length(c)>45 THEN RAISE EXCEPTION 'collection name too long for calibration companion table'; END IF;
  PERFORM public.morlet_context_relations(collection);
  rel:=to_regclass(format('%I.%I',s,c||'_calibration_sets'));
  IF rel IS NOT NULL THEN
    -- Do not silently change the approval authority on an idempotent enable call.
    IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname='morlet_calibration_guard'
      AND tgargs=convert_to(collection::text,'UTF8')||decode('00','hex')||
        convert_to(approver_name,'UTF8')||decode('00','hex')) THEN
      RAISE EXCEPTION 'calibration sets already enabled with another authority or collection identity';
    END IF;
    PERFORM public.morlet_calibration_bind_refs(collection);
    RETURN rel;
  END IF;
  EXECUTE format('CREATE TABLE %I.%I (
    set_id text NOT NULL CHECK(length(set_id) BETWEEN 1 AND 200), revision integer NOT NULL CHECK(revision>0),
    members jsonb NOT NULL, recording_ids text[] NOT NULL, manifest jsonb NOT NULL,
    manifest_text text NOT NULL, manifest_sha256 text NOT NULL,
    created_by name NOT NULL, created_at timestamptz NOT NULL,
    approved boolean NOT NULL DEFAULT false, approved_by name, approved_at timestamptz, approval_reason text,
    PRIMARY KEY(set_id,revision))',s,c||'_calibration_sets');
  rel:=to_regclass(format('%I.%I',s,c||'_calibration_sets'));
  EXECUTE format('CREATE TRIGGER morlet_calibration_guard BEFORE INSERT OR UPDATE OR DELETE ON %s
    FOR EACH ROW EXECUTE FUNCTION public.morlet_calibration_guard(%L,%L)',rel,collection::text,approver_name);
  EXECUTE format('CREATE TRIGGER morlet_calibration_truncate BEFORE TRUNCATE ON %s
    FOR EACH STATEMENT EXECUTE FUNCTION public.morlet_calibration_guard(%L,%L)',rel,collection::text,approver_name);
  PERFORM public.morlet_calibration_bind_refs(collection);
  RETURN rel;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_resolve_calibration_set(collection regclass,set_id text,revision integer)
RETURNS jsonb LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE saved jsonb; current_manifest jsonb; statuses jsonb:='[]'; m jsonb; item jsonb; fresh jsonb; status text;
BEGIN
  saved:=public.morlet_get_calibration_set(collection,set_id,revision);
  FOR m IN SELECT value FROM jsonb_array_elements(saved->'manifest'->'members') LOOP
    item:=jsonb_build_object('recording_id',m->'recording_id','start_sample',m->'start_sample',
      'end_sample',m->'end_sample','label_id',m->'label_id');
    BEGIN
      current_manifest:=public.morlet_calibration_capture(collection,jsonb_build_array(item));
      fresh:=current_manifest->'members'->0;
      -- Captured before the history existed (or under SQL 0.3.17, which did not record revisions): revision 0 now
      -- means no correction since, so it matches. Any later correction is a change even if it was reverted (#620).
      IF m->>'interpretation_revision'='unversioned' AND fresh->'interpretation_revision'='0'::jsonb THEN
        fresh:=jsonb_set(fresh,'{interpretation_revision}','"unversioned"');
      END IF;
      IF m->>'label_revision'='unversioned' AND fresh->'label_revision'='0'::jsonb THEN
        fresh:=jsonb_set(fresh,'{label_revision}','"unversioned"');
      END IF;
      status:=CASE
        WHEN fresh-'interpretation_revision'-'label_revision' IS DISTINCT FROM m-'interpretation_revision'-'label_revision'
          THEN 'changed'
        WHEN 'unknown' IN (fresh->>'interpretation_revision',m->>'interpretation_revision') THEN 'unverified'
        WHEN fresh=m THEN 'unchanged' ELSE 'changed' END;
      statuses:=statuses||jsonb_build_array(item||jsonb_build_object('status',status));
    EXCEPTION WHEN OTHERS THEN
      -- Do not turn corruption, permissions, cancellation or operational failures into missing evidence.
      IF SQLSTATE='P0001' AND (SQLERRM='member recording unavailable' OR
          SQLERRM='member requires a visible active label covering its interval' OR
          SQLERRM='source interval is incomplete or not fully visible' OR
          SQLERRM LIKE 'samples of recording % were compacted to level %') THEN
        statuses:=statuses||jsonb_build_array(item||jsonb_build_object('status','unavailable'));
      ELSE RAISE; END IF;
    END;
  END LOOP;
  RETURN jsonb_build_object('set_id',set_id,'revision',revision,'approved',saved->'approved',
    'manifest_sha256',saved->'manifest_sha256','members',statuses,
    'needs_review',EXISTS(SELECT 1 FROM jsonb_array_elements(statuses) x WHERE x->>'status'<>'unchanged'));
END $$;

CREATE OR REPLACE FUNCTION public.morlet_interpretation_revisions(collection regclass,recording_ids text[])
RETURNS TABLE(recording_id text,revision integer)
LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass;
BEGIN
  rel:=public.morlet_interpretation_relation(collection);
  IF rel IS NULL OR NOT public.morlet_interpretation_history_complete(rel) THEN RETURN; END IF;
  RETURN QUERY EXECUTE format('SELECT r.recording_id,coalesce((SELECT max(i.revision) FROM %s i
    WHERE i.recording_id=r.recording_id),0)::integer FROM %s r WHERE r.recording_id=ANY($1) ORDER BY 1',rel,collection)
    USING recording_ids;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_label_interpretation()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass; current_revision integer;
BEGIN
  IF TG_OP='UPDATE' THEN NEW.interpretation_revision:=OLD.interpretation_revision; RETURN NEW; END IF;
  rel:=public.morlet_interpretation_relation(public.morlet_companion_parent(TG_RELID));
  IF rel IS NOT NULL AND public.morlet_interpretation_history_complete(rel) THEN
    EXECUTE format('SELECT coalesce(max(revision),0) FROM %s WHERE recording_id=$1',rel)
      INTO current_revision USING NEW.recording_id;
  END IF;
  NEW.interpretation_revision:=current_revision;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_sample_utc(collection regclass,recording_id text,sample bigint,rho float8 DEFAULT NULL)
RETURNS TABLE(utc_ns numeric,uncertainty_ns numeric,basis text,assumes_linear_clock boolean,extrapolated boolean,segment integer)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rec record; rel regclass; num numeric; den numeric; period numeric; rho_rec float8; start_ns numeric;
  cur record; nxt record; prv record; fst record; found_cur boolean; found_nxt boolean; found_prv boolean; before_first boolean:=false;
  first_n bigint; seg integer; dn numeric; dt numeric; kind text; na bigint; nb bigint; ua numeric; ub numeric;
  same_next boolean; same_prev boolean; rho_used float8; active text; rc bigint;
BEGIN
  IF sample IS NULL OR sample<0 THEN RAISE EXCEPTION 'sample must be >= 0'; END IF;
  -- the checks, messages and order of morlet_time_pieces
  IF collection IS NULL OR recording_id IS NULL OR (rho IS NOT NULL AND NOT (rho>=0 AND rho<1)) THEN
    RAISE EXCEPTION 'collection and recording_id are required, and rho must be in [0, 1)';
  END IF;
  EXECUTE format('SELECT sample_rate_hz,metadata FROM %s WHERE recording_id=$1',collection) INTO rec USING recording_id;
  IF rec.sample_rate_hz IS NULL THEN RAISE EXCEPTION 'recording % does not exist or is not visible',recording_id; END IF;
  SELECT x.num,x.den INTO num,den FROM public.morlet_rate_ratio(rec.sample_rate_hz) x;
  period:=den*1000000000/num;
  IF rec.metadata#>'{time_axis,rho}' IS NOT NULL THEN
    IF jsonb_typeof(rec.metadata#>'{time_axis,rho}')<>'number' OR NOT ((rec.metadata#>>'{time_axis,rho}')::float8>=0
        AND (rec.metadata#>>'{time_axis,rho}')::float8<1) THEN
      RAISE EXCEPTION 'recording %: metadata time_axis.rho must be a number in [0, 1)',recording_id;
    END IF;
    rho_rec:=(rec.metadata#>>'{time_axis,rho}')::float8;
  END IF;
  SELECT to_regclass(format('%I.%I',n.nspname,cl.relname||'_time_anchors')) INTO rel
    FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  IF rel IS NOT NULL THEN
    active:=format('SELECT x.sample_offset AS n,x.utc_ns::numeric AS t,x.uncertainty_ns::numeric AS u,x.source,
      x.break_before FROM %1$s x WHERE x.recording_id=$1 AND NOT x.retracted
      AND NOT EXISTS(SELECT 1 FROM %1$s y WHERE y.supersedes=x.anchor_id) AND ',rel);
    EXECUTE active||'x.sample_offset<=$2 ORDER BY x.sample_offset DESC LIMIT 1' INTO cur USING recording_id,sample;
    GET DIAGNOSTICS rc = ROW_COUNT;
    found_cur:=rc>0;
    IF NOT found_cur THEN                     -- before the first anchor: piece 0, extrapolated from the first one
      EXECUTE active||'true ORDER BY x.sample_offset LIMIT 1' INTO cur USING recording_id;
      GET DIAGNOSTICS rc = ROW_COUNT;
      found_cur:=rc>0;
      before_first:=found_cur;
    END IF;
  END IF;
  IF rel IS NULL OR NOT found_cur THEN
    start_ns:=public.morlet_recording_start_ns(rec.metadata);
    IF start_ns IS NULL THEN RETURN; END IF;
    RETURN QUERY SELECT start_ns+(sample-0::bigint)*(den*1000000000)/num,NULL::numeric,'start+rate'::text,false,false,0;
    RETURN;
  END IF;
  EXECUTE active||'x.sample_offset>$2 ORDER BY x.sample_offset LIMIT 1' INTO nxt USING recording_id,cur.n;
  GET DIAGNOSTICS rc = ROW_COUNT;
  found_nxt:=rc>0;
  EXECUTE active||'x.sample_offset<$2 ORDER BY x.sample_offset DESC LIMIT 1' INTO prv USING recording_id,cur.n;
  GET DIAGNOSTICS rc = ROW_COUNT;
  found_prv:=rc>0;
  IF found_prv THEN
    EXECUTE active||'true ORDER BY x.sample_offset LIMIT 1' INTO fst USING recording_id;
    first_n:=fst.n;
    -- the active breaks after the first anchor, up to this one (a break on the first anchor starts no segment): the
    -- rows not retracted, less those a revision superseded (found from the revisions, which are few)
    EXECUTE format('SELECT (SELECT count(*) FROM %1$s x WHERE x.recording_id=$1 AND x.break_before AND NOT x.retracted
        AND x.sample_offset>$2 AND x.sample_offset<=$3)
      -(SELECT count(*) FROM %1$s y JOIN %1$s x ON x.anchor_id=y.supersedes WHERE y.supersedes IS NOT NULL
        AND x.recording_id=$1 AND x.break_before AND NOT x.retracted AND x.sample_offset>$2 AND x.sample_offset<=$3)',rel)
      INTO seg USING recording_id,first_n,cur.n;
  ELSE
    seg:=0;
  END IF;
  -- the piece of anchor cur, as morlet_time_pieces builds it: its slope from the next anchor of the segment, else from
  -- the previous one, else the declared rate
  same_next:=found_nxt AND NOT nxt.break_before;
  same_prev:=found_prv AND NOT cur.break_before;
  IF same_next THEN
    kind:='between'; dn:=(nxt.n-cur.n)::numeric; dt:=nxt.t-cur.t; na:=cur.n; nb:=nxt.n; ua:=cur.u; ub:=nxt.u;
  ELSIF same_prev THEN
    kind:='after'; dn:=(cur.n-prv.n)::numeric; dt:=cur.t-prv.t; na:=prv.n; nb:=cur.n; ua:=prv.u; ub:=cur.u;
  ELSE
    kind:='after'; dn:=num; dt:=den*1000000000;
  END IF;
  -- the caller's ρ, else the recording's, else the default of the anchors involved (none if one is an estimate)
  rho_used:=coalesce(rho,rho_rec,CASE WHEN public.morlet_default_clock_rho(cur.source) IS NULL
      OR (same_next AND public.morlet_default_clock_rho(nxt.source) IS NULL)
      OR (NOT same_next AND same_prev AND public.morlet_default_clock_rho(prv.source) IS NULL)
    THEN NULL ELSE public.morlet_default_clock_rho(cur.source) END);
  IF before_first THEN kind:='before'; END IF;
  RETURN QUERY SELECT cur.t+(sample-cur.n)*dt/dn,
    public.morlet_piece_uncertainty(kind,sample,cur.n,cur.u,na,nb,ua,ub,rho_used,period),
    'anchors'::text,rho_used IS NULL,kind IN ('before','after') AND sample<>cur.n,seg;
END $$;

DO $morlet_upgrade$
DECLARE c regclass; refs regclass;
BEGIN
  FOR c IN SELECT to_regclass(format('%I.%I',n.nspname,left(cl.relname,-length('_calibration_sets'))))
    FROM pg_trigger t JOIN pg_class cl ON cl.oid=t.tgrelid JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE t.tgname='morlet_calibration_guard' AND right(cl.relname,17)='_calibration_sets' ORDER BY 1
  LOOP
    IF c IS NOT NULL THEN
      PERFORM public.morlet_calibration_bind_refs(c);
      SELECT to_regclass(format('%I.%I',n.nspname,cl.relname||'_calibration_refs')) INTO refs
        FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=c;
      IF EXISTS(SELECT 1 FROM pg_depend WHERE classid='pg_class'::regclass AND objid=refs AND deptype='e') THEN
        EXECUTE format('ALTER EXTENSION pg_morlet DROP TABLE %s',refs);
      END IF;
    END IF;
  END LOOP;
END $morlet_upgrade$;
